from save_review import save
import json,re
from pathlib import Path
D=Path(__file__).resolve().parents[2];corpus={a['number']:a for a in json.loads((D/'全书分段底稿.json').read_text())}
def finish(n,ed,notes=None,terms=None,additions=None):
 bs={int(b['id'][-4:]):b for b in corpus[n]['blocks']}
 for i,b in bs.items():
  if b.get('language')!='en' or i+1 not in bs or bs[i+1].get('language')!='zh':continue
  s=ed.get(i+1,bs[i+1]['text'])
  if 'Dead World' in b['text']:s=s.replace('死亡世界','死寂世界')
  if re.search(r'sub.?sector',b['text'],re.I):s=s.replace('分区','次星区')
  for x,y in [('哈洗录深渊','哈冼录深渊'),('戈尔根纳河段','戈尔根纳疆域'),('杰里科河段','杰里科疆域'),('阿德兰蒂斯','阿德兰提斯')]:s=s.replace(x,y)
  if s!=bs[i+1]['text']:ed[i+1]=s
 save(n,ed,notes=notes,terms=terms,additions=additions)
finish(876,{2:'天堂世界，也称享乐世界或花园世界，是一类以非凡自然美景著称的行星。它们的自然条件非常适合人类居住，工业极少，人口也不多。帝国没有向所有这类稀有行星大规模移民、发展工业，而是将其中一些保持在自然状态，供重要帝国官员和服役者休养。在这里，战士也能锤炼身心，研习深奥的战争哲学，精进武艺。这些世界还是富可敌国的帝国贵族的安逸居所。不过，它们的生活方式有时也会滋生诱惑与异端。',4:'花园世界属于文明世界的一个子类。',17:'欧律狄刻（原天堂世界）——朦胧星域；现归属不明，原属帝国；已无人居住，现为死寂世界。',21:'艾克斯（原天堂世界）——极限星域；帝国；现为死亡世界，过去也曾是农业世界。',23:'克利泰恩（原天堂世界）——现归属不明，原属灵族；现为死寂世界，过去也是蛮荒灵族世界。',25:'奎迪斯——朦胧星域；帝国；人口不详且流动，常住居民估计不足500万。',29:'瑞斯——朦胧星域；帝国；人口6.4亿。',31:'罗法农（原天堂世界）——可能位于暴风星域；帝国；灭绝令实施前人口为18亿9330万，现已无人居住，成为死寂世界。'},notes={2:'pleasure world 按休养享乐语境译享乐世界，不用含义含糊的快乐世界；some 强调并非所有此类世界都完整保持自然状态。',21:'补回原译遗漏的 former Agri World；本行英文确为 Death World，保留死亡世界。',23:'Exodite World 为蛮荒灵族世界，不是普通流亡地。'},terms=[('Paradise World','天堂世界'),('Pleasure World','享乐世界'),('Garden World','花园世界')])
finish(877,{2:'刑罚世界是帝国用来关押触犯帝国法律的人类罪犯的世界，其最高负责人称为看守总督。',4:'刑罚殖民地关押着形形色色的人。有的收容上百万名强奸犯、杀人犯、异端、分离主义者、窃贼、变种人，以及犯下其他各类罪行的人。他们都是被帝国厌弃、抛弃的人。',6:'刑罚世界既可能关押罪行较轻的惯犯，也可能收押杀人犯、强奸犯和异端等最严重的罪犯。囚犯依罪名和刑期被分置于特定的监禁尖塔。罪行最重的人可能被判处死刑，却在执行前继续作为奴工，从事采矿或其他重体力劳动，长达数年甚至数十年。',8:'被判有罪的儿童也会被送往这些监狱。原文称，目睹犯罪的少年可能因年幼而获减刑，只被判在刑罚营服数年苦役。无辜的帝国卫队士兵有时也会因未曾犯下的罪行被判终身监禁。',10:'Imperial Penal Colony 帝国刑罚殖民地',12:'Lost Hope 失落希望（原稿另译无望星）'},notes={6:'Interment 通常指埋葬，依关押与分区语境疑为 Internment 的误拼，暂译监禁尖塔并保留英文原文。recidivist 本身表示再犯者，并不必然是轻罪；原文这样归类，照实保留。',8:'英文写 witnessed a crime（目睹犯罪），并非 witnessed committing a crime（被目击犯罪）；按现有英文译出，并标明此可疑表述待核，未擅改成确实犯罪。',12:'沿869 Lost Hope 失落希望；保留本篇原稿别名无望星。'},terms=[('Penal World','刑罚世界'),('Penal Colony','刑罚殖民地'),('Governor-Warden','看守总督'),('Interment Spires','监禁尖塔')])
finish(878,{2:'圣地世界，又可称大教堂世界，是奉献给某位帝国圣人的行星，往往也以这位圣人的名字命名。英文 Shrine World 亦可连写为 Shrineworld。这些世界由国教会直接统治，吸引帝国各地的大量朝圣者。帝国的虔敬之地也有黑暗的对应物：在一些堕落世界，居民日夜向黑暗诸神祈祷。帝国不会容忍这些充斥亵渎献祭与血腥仪式的地方长久存在。许多圣地世界是帝国圣徒的永眠之所，整颗神圣星球的表面都布满圣人陵墓与宏伟的巨石大教堂。',6:'圣地世界常年笼罩在熏香与烛烟之中。油脂世界会向邻近圣地世界输出大量蜡烛。不过，这些蜡烛由人体熬炼出的脂肪制成，往往散发出难闻的气味。',8:'大多数圣地世界也属于其他世界类别。例如哈吉亚同时是农业世界，希罗多尔则是巢都世界。它们都与所奉敬的圣人关系密切，可能是其出生地或殉道之地。',13:'阿尔玛瑞特（原圣地世界）——现归属混沌恐虐，原属帝国；现为恶魔世界，过去也是堡垒世界。',17:'阿克’拉斯——朦胧星域；杰米农星系；帝国。',19:'奥泰加——帝国；也是死亡世界。',27:'坎蒂库拉——原属帝国；曾遭怀言者蹂躏。',37:'哈吉亚——太平星域；安息日诸世界；帝国；也是农业世界。',47:'卡图尔——朦胧星域；斯卡鲁斯星区；帝国；正在重新移民，目前居民稀少。',57:'门达克斯——极限星域；灾祸降临星系；帝国。',63:'虔诚星（原圣地世界）——现归属不明，先后曾属帝国与恶魔；现为死寂世界，过去也是恶魔世界。',77:'桑蒂亚（原圣地世界）——朦胧星域；帝国；人口栏记为无，当前状态不明。',93:'圣经星——帝国；曾遭恶魔入侵。'},notes={2:'Shrineworlds 是连写变体，不构成另一个“神殿世界”分类。not suffered continued existence 表示不被容忍长期存在，并非证明所有这类世界都已被消灭。',17:'原译“朦胧星炬”应为朦胧星域。',22:'Belatis IV 按原拼写保留，不能仅凭近似字形与 Betalis IV 自动合并。',27:'ravaged 表示蹂躏破坏，并不足以断言整颗世界彻底毁灭。'},terms=[('Shrine World','圣地世界'),('Shrineworld','圣地世界'),('Cathedral World','大教堂世界'),('Tallow World','油脂世界'),('Gundora','贡多拉')])
finish(879,{2:'战争世界是被划为战区的行星。帝国疆域内，有大量世界属于这一类别。',4:'帝国始终身陷战争，整颗行星都可能在战火中燃烧。一场大规模战役可以席卷数十个星系、数百个世界；其中许多在持续数十年的全球战斗中，遭轨道轰炸与炮火彻底摧残。长期战区如同地狱，死亡转瞬即至。帝国能够投入数百万人的庞大军队，在残破地表缓慢推进，将城市夷为瓦砾。雇佣兵蜂拥而来，希望很快就能带着满载酬金的舰船离开。逃兵与越狱者结成海盗团，袭击无力自卫的舰船，或成群游荡在饱受战争蹂躏的星球上，劫掠杀戮。战斗结束后，内政部会从人口过密的世界调来殖民者，重新填补这些世界的人口。然而帝国行政运转迟缓，一颗世界可能荒废数百年，才有人着手重新移民。这样的地方是帝国最可怖的景象之一：生态毁坏，地壳开裂，城市焚尽，平原遍布死者白骨。',9:'黄泉四号——帝国部队曾在此对抗乌格洛特大蛮干！的欧克兽人。',13:'阿瓦兰——帝国部队正在镇压混沌教派起义；也是巢都世界。',21:'布恩港——太平星域；卡布利斯星系；该世界及整个星系正遭格拉格纳兹大蛮干！攻击。',23:'塞特斯次星——朦胧星域；普拉加次星区；责难者战团曾在此对抗黑色军团；也是墓地世界。',27:'南十字星——太平星域；卡布利斯星系；该世界及整个星系正遭格拉格纳兹大蛮干！攻击。',35:'埃梅勒——太平星域；该世界及整个卡布利斯星系正遭格拉格纳兹大蛮干！攻击；也是少女世界。',37:'埃斯卡巴——阿尔法军团的混沌星际战士科莫斯·赫克斯洛与科因·詹库斯，曾率各自军队在此相互交战。',41:'格尔米罗一号——朦胧星域；卡利西斯星区；位于马尔坎边区的顺银河自转方向一侧。',43:'格尔米罗二号——朦胧星域；卡利西斯星区；位于马尔坎边区的顺银河自转方向一侧。',45:'格尔米罗三号——朦胧星域；卡利西斯星区；位于马尔坎边区的顺银河自转方向一侧。',47:'金加——正面临混沌教派起义，叛乱者得到恶魔支援；灰骑士已赶来救援。',49:'光荣星——太平星域；卡布利斯星系；该世界及整个星系正遭格拉格纳兹大蛮干！攻击。',53:'贡多拉——特拉托尔星系；帝国正在抵抗混沌入侵；也是圣地世界。',67:'库尔特——朦胧星域；卡利西斯星区、边陲；自欧克首次入侵起，争夺该世界的战争已持续83年。',79:'穆利斯四号——卡塔昌部队正在这里与太空死灵作战；也是丛林世界。',87:'费顿·阿尔法——也是研究站；正遭恶魔入侵，灰骑士曾英勇抵抗这场邪恶攻势。',93:'拉沙德主星——曾遭变幻神谕战帮入侵；也是工业世界和农业世界。',99:'撒拉弗一号——当地居民正发生一场受异形煽动的叛乱；也是工业世界。',103:'坦佩里斯——太平星域；卡布利斯星系；该世界及整个星系正遭格拉格纳兹大蛮干！攻击；也是巢都世界。',107:'特伦奇——朦胧星域；卡利西斯星区、阿德兰提斯次星区；帝国军队正在镇压凶暴的变种人起义；也是巢都世界。',112:'警戒星——朦胧星域；纳克蒙德走廊、警戒星系；人口约1670亿；正遭欧克、基因窃取者教派、灵族与黑暗灵族攻击。'},notes={4:'planet-spanning 是遍及行星表面的战争，非跨行星作战；wheels grind slowly 比喻行政运作迟缓，并非车轮磨损。',37:'with each other 在这里表示双方相互交战，原译“并肩作战”把敌对关系颠倒。',47:'with the aid of Daemons 的修饰关系按混沌起义获恶魔援助理解，避免把恶魔写成守军盟友。',49:'英文没有“也是少女世界”，删除原译无依据增句。',93:'Oracles of Change 是混沌战帮名，暂译变幻神谕；官方中文待核。',99:'Xeno 指异形，不是“异型”；inspired rebellion 在此为受其煽动的叛乱。',113:'原稿此行缺少中文，依英文补译。'},terms=[('War World','战争世界'),('Waaagh! Gragnatz','格拉格纳兹大蛮干！'),('Waaagh! Uggrot','乌格洛特大蛮干！'),('Oracles of Change','变幻神谕'),('Praga Sub-Sector','普拉加次星区'),('Spinward','顺银河自转方向')],additions={113:'赞德罗斯——极限战士与太空死灵正在这里交战。'})
finish(880,{2:'哨兵世界，又称堡垒世界（Bastion World），是帝国统帅基里曼在大裂隙形成后设立的新行星分类。这些世界旨在构成不可攻破的屏障，抵御防线之外、肆虐帝国暗面的种种恐怖。',7:'克鲁——极限星域；天使光环战役期间曾在此爆发一系列战斗。',9:'诺纳沃尔——朦胧星域；纳克蒙德地区；位于纳克蒙德走廊南部。',11:'警戒星——朦胧星域；纳克蒙德地区、警戒星系；人口约1670亿；野兽之战发生地。它坐落在纳克蒙德走廊入口处；这条走廊是当时唯一已知能够“稳定”穿越大裂隙的通道。'},notes={2:'Bastion World 为本篇 Sentinel World 别称，保留英文以区别872篇传统 Fortress World 分类，两者不能因同译堡垒世界就合并。',9:'英文只列 Nachmund，未明确行政等级，译作地区，不擅自补成次星区。',11:'英文167,000,000,000为1670亿，原译仅167亿，少了一位。War of Beasts为警戒星野兽之战，区别M32的War of the Beast野兽战争。only known 依本段资料时点理解，未据此断言所有时代都仅有一条通道。'},terms=[('Sentinel World','哨兵世界'),('Bastion World','堡垒世界（哨兵世界别称）'),('Angel\'s Halo','天使光环')])
